settings.liquid:
{%- comment -%}
CURVJEANS · Performance Creators Signup Page (NL/EN auto)
- Shows NL copy when URL contains /nl
- Otherwise shows EN copy
{%- endcomment -%}

{%- assign is_nl = false -%}
{%- if request.path contains '/nl' -%}{%- assign is_nl = true -%}{%- endif -%}

<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,700&display=swap" rel="stylesheet">

<style>
  .pc-wrap {
    --black:   #0f0f0f;
    --white:   #ffffff;
    --grey-50: #f7f7f7;
    --grey-100:#efefef;
    --grey-200:#d8d8d8;
    --grey-400:#9a9a9a;
    --line:    rgba(0,0,0,.09);
    --radius:  12px;
    --serif:   'DM Serif Display', Georgia, serif;
    --sans:    'DM Sans', system-ui, sans-serif;
  }

  .pc-wrap {
    font-family: var(--sans);
    color: var(--black);
    background: var(--white);
    max-width: 1160px;
    margin: 0 auto;
    padding: 0 20px clamp(60px,8vw,100px);
  }
  .pc-wrap *, .pc-wrap *::before, .pc-wrap *::after { box-sizing: border-box; }

  /* HERO */
  .pc-hero {
    padding: clamp(40px,7vw,88px) 0 clamp(32px,5vw,56px);
    max-width: 720px;
  }
  @media (min-width: 681px) {
    .pc-hero {
      max-width: 100%;
      text-align: center;
      align-items: center;
    }
    .pc-hero .pc-hero-sub {
      margin-left: auto;
      margin-right: auto;
    }
    .pc-hero .pc-trust {
      justify-content: center;
    }
  }
  .pc-eyebrow {
    font-family: var(--sans);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--grey-400);
    margin: 0 0 18px;
  }
  .pc-h1 {
    font-family: var(--serif);
    font-size: clamp(34px,5vw,60px);
    font-weight: 400;
    line-height: 1.06;
    margin: 0 0 22px;
    letter-spacing: -.01em;
  }
  .pc-h1 em { font-style: italic; }
  .pc-hero-sub {
    font-size: clamp(15px,1.6vw,18px);
    color: var(--grey-400);
    line-height: 1.65;
    margin: 0 0 32px;
    max-width: 560px;
  }

  /* CTA BUTTON */
  .pc-btn {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    background: var(--black);
    color: var(--white);
    font-family: var(--sans);
    font-size: 14px;
    font-weight: 700;
    letter-spacing: .02em;
    padding: 15px 28px;
    border-radius: 999px;
    text-decoration: none;
    transition: opacity .15s, transform .15s;
    white-space: nowrap;
    border: none;
    cursor: pointer;
  }
  .pc-btn:hover { opacity: .82; transform: translateY(-1px); }
  .pc-btn svg { width: 14px; height: 14px; flex-shrink: 0; }

  .pc-trust {
    font-size: 12px;
    color: var(--grey-400);
    margin-top: 18px;
    display: flex;
    align-items: center;
    gap: 7px;
  }
  .pc-trust::before {
    content: '';
    display: inline-block;
    width: 5px; height: 5px;
    background: var(--grey-200);
    border-radius: 50%;
    flex-shrink: 0;
  }

  /* DIVIDER */
  .pc-hr {
    border: none;
    border-top: 1px solid var(--line);
    margin: clamp(40px,5vw,60px) 0;
  }

  /* SECTION LABELS */
  .pc-label {
    font-family: var(--sans);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--grey-400);
    margin: 0 0 10px;
  }
  .pc-h2 {
    font-family: var(--serif);
    font-size: clamp(24px,3vw,38px);
    font-weight: 400;
    line-height: 1.1;
    margin: 0 0 8px;
  }
  .pc-section-sub {
    font-size: 16px;
    color: var(--grey-400);
    line-height: 1.6;
    max-width: 540px;
    margin: 0 0 28px;
  }

  /* LEADERBOARD LINK */
  .pc-leaderboard {
    display: inline-flex;
    align-items: center;
    gap: 14px;
    background: var(--black);
    border: 1.5px solid var(--black);
    border-radius: 999px;
    padding: 14px 22px;
    margin-bottom: 32px;
    text-decoration: none;
    color: var(--white);
    transition: opacity .15s, transform .15s;
    max-width: 100%;
    cursor: pointer;
  }
  .pc-leaderboard:hover { opacity: .82; transform: translateY(-1px); }
  .pc-leaderboard__icon {
    width: 32px; height: 32px;
    background: rgba(255,255,255,.15);
    border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
  }
  .pc-leaderboard__icon svg { width: 17px; height: 17px; }
  .pc-leaderboard__body { display: flex; flex-direction: column; gap: 2px; }
  .pc-leaderboard__cue { font-size: 12px; color: rgba(255,255,255,.65); }
  .pc-leaderboard__cta {
    font-size: 13px;
    font-weight: 700;
    color: var(--white);
    display: flex;
    align-items: center;
    gap: 5px;
  }
  .pc-leaderboard__cta svg { width: 11px; height: 11px; }

  /* VIDEO SECTION centered on desktop */
  @media (min-width: 681px) {
    .pc-videos-section {
      text-align: center;
    }
    .pc-videos-section .pc-section-sub {
      margin-left: auto;
      margin-right: auto;
    }
    .pc-videos-section .pc-leaderboard {
      margin-left: auto;
      margin-right: auto;
    }
  }

  /* VIDEO GRID */
  .pc-videos {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
  }
  @media (max-width: 680px) { .pc-videos { grid-template-columns: 1fr; gap: 20px; } }

  .pc-video-card {
    position: relative;
    border-radius: var(--radius);
    overflow: hidden;
    background: var(--grey-50);
    aspect-ratio: 9/16;
    border: 1px solid var(--line);
  }
  .pc-video-card video {
    width: 100%; height: 100%;
    object-fit: cover;
    display: block;
  }
  .pc-video-placeholder {
    width: 100%; height: 100%;
    display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    gap: 10px;
    background: var(--grey-50);
    padding: 24px;
    text-align: center;
  }
  .pc-video-placeholder__play {
    width: 44px; height: 44px;
    border-radius: 50%;
    background: var(--grey-200);
    display: flex; align-items: center; justify-content: center;
  }
  .pc-video-placeholder__play svg { width: 18px; height: 18px; margin-left: 3px; }
  .pc-video-placeholder p { font-size: 11px; color: var(--grey-400); margin: 0; line-height: 1.5; }

  .pc-video-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(to top, rgba(0,0,0,.76) 0%, transparent 52%);
    display: flex; flex-direction: column; justify-content: flex-end;
    padding: 18px 16px;
    pointer-events: none;
  }
  .pc-video-format {
    font-size: 10px; font-weight: 800;
    letter-spacing: .09em; text-transform: uppercase;
    color: rgba(255,255,255,.55);
    margin: 0 0 5px;
  }
  .pc-video-hook {
    color: #fff;
    font-family: var(--sans);
    font-size: 14px; font-weight: 700;
    line-height: 1.3; margin: 0;
  }

  /* TONE CALLOUT */
  .pc-tone {
    margin-top: 20px;
    background: var(--grey-50);
    border: 1px solid var(--line);
    border-radius: var(--radius);
    padding: 18px 22px;
    display: flex; gap: 14px; align-items: flex-start;
  }
  .pc-tone__label { font-size: 12px; font-weight: 700; margin: 0 0 3px; }
  .pc-tone__text { font-size: 14px; color: var(--grey-400); font-style: italic; line-height: 1.6; margin: 0; }

  /* TWO COL */
  .pc-two-col {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: clamp(24px,4vw,56px);
    align-items: start;
  }
  @media (max-width: 680px) { .pc-two-col { grid-template-columns: 1fr; } }

  .pc-checklist {
    list-style: none; padding: 0; margin: 0;
    display: flex; flex-direction: column; gap: 13px;
  }
  .pc-checklist li {
    display: flex; gap: 11px; align-items: flex-start;
    font-size: 15px; line-height: 1.55;
  }
  .pc-check-icon {
    flex-shrink: 0; margin-top: 3px;
    width: 20px; height: 20px;
    background: var(--grey-100); border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
  }
  .pc-check-icon svg { width: 11px; height: 11px; }

  /* EARN CARD */
  .pc-earn-card {
    background: var(--white);
    color: var(--black);
    border: 1.5px solid var(--grey-200);
    border-radius: calc(var(--radius) + 2px);
    padding: clamp(24px,3vw,40px);
    text-align: left;
  }
  .pc-earn-card .pc-label { color: var(--grey-400); }
  .pc-earn-card .pc-h2 { color: var(--black); margin-bottom: 20px; }
  .pc-earn-card .pc-h2 em { font-style: italic; color: var(--grey-400); }
  .pc-earn-list {
    list-style: none; padding: 0; margin: 0;
    display: flex; flex-direction: column; gap: 12px;
  }
  .pc-earn-list li {
    font-size: 15px; color: var(--black); line-height: 1.6;
    padding-left: 14px;
    position: relative;
  }
  .pc-earn-list li span {
    display: inline;
  }
  .pc-earn-list li::before {
    content: '·';
    position: absolute;
    left: 0; top: 0;
    color: var(--grey-400);
    font-size: 20px;
    line-height: 1.3;
  }
  .pc-earn-list b { color: var(--black); font-weight: 700; }

  /* FORM SECTION */
  .pc-form-section {
    background: var(--grey-50);
    border: 1px solid var(--line);
    border-radius: calc(var(--radius) + 4px);
    padding: clamp(28px,4vw,52px);
    scroll-margin-top: 20px;
  }
  .pc-form-iframe-wrap {
    margin-top: 22px;
    border-radius: 10px;
    overflow: hidden;
    border: 1px solid var(--line);
    background: var(--white);
  }
  .pc-form-iframe-wrap iframe {
    width: 100% !important; max-width: 100%;
    border: none; display: block;
    min-height: 1100px;
  }

  /* STICKY MOBILE CTA */
  .pc-sticky { display: none; }
  @media (max-width: 680px) {
    .pc-sticky {
      display: block;
      position: fixed; bottom: 0; left: 0; right: 0;
      padding: 12px 16px;
      background: rgba(255,255,255,.96);
      backdrop-filter: blur(8px);
      border-top: 1px solid var(--line);
      z-index: 99;
    }
    .pc-sticky .pc-btn {
      width: 100%;
      justify-content: center;
      background: var(--black);
      color: var(--white);
    }
  }
</style>

<div class="pc-wrap">

  <!-- HERO -->
  <header class="pc-hero">
    <p class="pc-eyebrow">Performance Creators</p>

    <h1 class="pc-h1">
      {% if is_nl %}
        Jij maakt de video's.<br>
        Wij draaien ze als ads.<br>
        Jij <em>verdient</em> op elke sale.
      {% else %}
        You make the videos.<br>
        We run them as ads.<br>
        You <em>earn</em> on every sale.
      {% endif %}
    </h1>

    <p class="pc-hero-sub">
      {% if is_nl %}
        Geen minimum volgers. Geen standaard influencer deal. Wij steken adbudget achter wat werkt — en jij verdient commissie én zichtbaarheid.
      {% else %}
        No follower minimum. No post-and-forget deal. We put ad budget behind what performs — and you earn commission plus visibility.
      {% endif %}
    </p>

    <a href="#apply-form" class="pc-btn">
      {% if is_nl %}Nu aanmelden{% else %}Apply now{% endif %}
      <svg viewBox="0 0 14 14" fill="none"><path d="M2 7h10M7.5 3l4 4-4 4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
    </a>

    <p class="pc-trust">
      {% if is_nl %}8% netto commissie · Maandelijkse uitbetaling · Geen minimum volgers{% else %}8% net commission · Monthly payout · No follower minimum{% endif %}
    </p>
  </header>

  <hr class="pc-hr">

  <!-- VIDEO EXAMPLES -->
  <section class="pc-videos-section">
    <p class="pc-label">{% if is_nl %}Hoe het eruitziet{% else %}What it looks like{% endif %}</p>
    <h2 class="pc-h2">{% if is_nl %}Video's die verkopen{% else %}Videos that sell{% endif %}</h2>
    <p class="pc-section-sub">
      {% if is_nl %}
        Geen modeshots. Geen filters. Gewoon echte vrouwen, eerlijke video's.
      {% else %}
        No fashion shoots. No filters. Just real women, honest videos.
      {% endif %}
    </p>

    <!-- Leaderboard link -->
    <a href="https://creators.curvjeans.com/boards/" target="_blank" rel="noopener" class="pc-leaderboard">
      <div class="pc-leaderboard__icon">
        <svg viewBox="0 0 24 24" fill="none">
          <path d="M18 20V10M12 20V4M6 20v-6" stroke="white" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </div>
      <div class="pc-leaderboard__body">
        <span class="pc-leaderboard__cue">
          {% if is_nl %}Benieuwd wat onze huidige creators verdienen?{% else %}Curious what our current creators earn?{% endif %}
        </span>
        <span class="pc-leaderboard__cta">
          {% if is_nl %}Bekijk het leaderboard{% else %}See the leaderboard{% endif %}
          <svg viewBox="0 0 12 12" fill="none"><path d="M2.5 6h7M6.5 3l3 3-3 3" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </span>
      </div>
    </a>

    <!-- Video grid -->
    <div class="pc-videos">

      <div class="pc-video-card">
        <video src="https://cdn.shopify.com/videos/c/o/v/907d5cb1a5ec42c98163c76aa3fe9065.mp4" autoplay muted loop playsinline></video>
      </div>

      <div class="pc-video-card">
        <video src="https://cdn.shopify.com/videos/c/o/v/597604d2992e43888223987eef0a5436.mp4" autoplay muted loop playsinline></video>
      </div>

      <div class="pc-video-card">
        <video src="https://cdn.shopify.com/videos/c/o/v/e7d6b89d23714f2a88f221a608696757.mp4" autoplay muted loop playsinline></video>
      </div>

    </div>

    <!-- Tone callout -->
    <div class="pc-tone">
      <span style="font-size:18px;flex-shrink:0;margin-top:1px;">💬</span>
      <div>
        <p class="pc-tone__label">{% if is_nl %}Hoe klinkt het{% else %}The tone{% endif %}</p>
        <p class="pc-tone__text">
          {% if is_nl %}
            Eerlijk en direct — geen fashion vibe, geen filters. Praat als een echte vrouw. "Ik dacht altijd dat mijn figuur het probleem was. Totdat ik deze jeans paste."
          {% else %}
            Honest and direct — no fashion vibe, no filters. Talk like a real woman. "I always thought my body was the problem. Until I tried these jeans."
          {% endif %}
        </p>
      </div>
    </div>
  </section>

  <hr class="pc-hr">

  <!-- FIT + EARN -->
  <section class="pc-two-col">

    <div>
      <p class="pc-label">{% if is_nl %}Past dit bij jou?{% else %}Is this for you?{% endif %}</p>
      <h2 class="pc-h2" style="margin-bottom:20px;">{% if is_nl %}Dit zoeken wij{% else %}What we look for{% endif %}</h2>
      <ul class="pc-checklist">
        {% if is_nl %}
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Je snapt hoe aandacht werkt in short-form video</li>
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Je kunt bewezen video-concepten nabouwen in jouw stijl</li>
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Je levert zelfstandig en op tijd</li>
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Je denkt lange termijn — niet één post, maar samen bouwen</li>
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Je staat open voor feedback om beter te presteren</li>
        {% else %}
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>You understand how attention works in short-form video</li>
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>You can remake proven video concepts in your own style</li>
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>You deliver independently and on time</li>
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>You think long-term — not one post, but building together</li>
          <li><span class="pc-check-icon"><svg viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>You're open to feedback to improve performance</li>
        {% endif %}
      </ul>
    </div>

    <div class="pc-earn-card">
      <p class="pc-label">{% if is_nl %}Wat jij verdient{% else %}What you earn{% endif %}</p>
      <h2 class="pc-h2">{% if is_nl %}Goed presteren = <em>goed verdienen</em>{% else %}Perform well = <em>earn well</em>{% endif %}</h2>
      <ul class="pc-earn-list">
        {% if is_nl %}
          <li><span><b>8% commissie</b> op netto omzet die jouw video's genereren</span></li>
          <li><span>Meerdere CURVJEANS producten toegestuurd</span></li>
          <li><span>Persoonlijke begeleiding over wat werkt en verkoopt</span></li>
          <li><span>Wij promoten jouw Instagram als de content goed genoeg is → meer volgers, meer commissie</span></li>
          <li><span><b>Maandelijkse uitbetaling</b> met duidelijke performance inzichten</span></li>
        {% else %}
          <li><span><b>8% commission</b> on net revenue your videos generate</span></li>
          <li><span>Multiple CURVJEANS products sent to you</span></li>
          <li><span>Personal guidance on what content performs and sells</span></li>
          <li><span>We promote your Instagram when content performs → more followers, more commission</span></li>
          <li><span><b>Monthly payout</b> with clear performance insights</span></li>
        {% endif %}
      </ul>
    </div>

  </section>

  <hr class="pc-hr">

  <!-- FORM -->
  <section class="pc-form-section" id="apply-form">
    <p class="pc-label">{% if is_nl %}Aanmelden{% else %}Apply{% endif %}</p>
    <h2 class="pc-h2">{% if is_nl %}Klaar om te starten?{% else %}Ready to get started?{% endif %}</h2>
    <p class="pc-section-sub" style="margin-bottom:0;">
      {% if is_nl %}Vul het formulier in. We reageren binnen 3 werkdagen.{% else %}Fill out the form below. We'll get back to you within 3 business days.{% endif %}
    </p>
    <div class="pc-form-iframe-wrap">
      <iframe
        src="https://docs.google.com/forms/d/e/1FAIpQLSfwsrZw45wtrX9Z9kT4tx77eo8mV2rGnAZBMZMu8zi7KUhviA/viewform?embedded=true"
        width="640"
        height="1737"
        frameborder="0"
        marginheight="0"
        marginwidth="0"
      >Loading…</iframe>
    </div>
  </section>

</div>

<!-- Sticky mobile CTA -->
<div class="pc-sticky" id="pc-sticky">
  <a href="#apply-form" class="pc-btn">
    {% if is_nl %}Nu aanmelden{% else %}Apply now{% endif %}
    <svg viewBox="0 0 14 14" fill="none"><path d="M2 7h10M7.5 3l4 4-4 4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
  </a>
</div>

<script>
(function(){
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      var t = document.querySelector(this.getAttribute('href'));
      if(t){ e.preventDefault(); t.scrollIntoView({ behavior:'smooth', block:'start' }); }
    });
  });
  var form = document.getElementById('apply-form');
  var bar  = document.getElementById('pc-sticky');
  if(form && bar && 'IntersectionObserver' in window){
    new IntersectionObserver(function(entries){
      bar.style.display = entries[0].isIntersecting ? 'none' : '';
    },{ threshold:0.05 }).observe(form);
  }
})();
</script>
